import {metrics,MODULES} from './engine.mjs';
import {FABRIC_MODEL,WORKLOADS} from './fabric.mjs';

const fabricPoint=p=>`${p.x*100+50},${p.y*100+50}`;
const fabricColor=load=>load>=1?'#f28e76':load>=.65?'#e4bd70':'#70dcb4';
const fabricPercent=n=>(n*100).toFixed(1)+'%';
const fabricDelta=n=>(n>0?'+':'')+n.toFixed(1);
export function renderFabricOverlay(grid,state,selectedId=null){
 grid.querySelector('.fabric-overlay')?.remove();
 const layer=state.fabricLayer??'congestion';const label=grid.closest('.chip-workspace').querySelector('.x-label');label.textContent=layer==='off'?'DIE FLOORPLAN / TOP VIEW':selectedId!==null?'SELECTED MODULE / COMMUNICATION ROUTES':layer==='routes'?'XY ROUTES / REQUEST · DATA · REFILL':'MESH / 绿 <65% · 黄 <100% · 红 ≥100%';if(layer==='off')return;
 const f=metrics(state).fabric;let drawing='';
 if(layer==='routes'||selectedId!==null){const relevant=selectedId===null?f.flows:f.flows.filter(flow=>flow.fromId===selectedId||flow.toId===selectedId);drawing=relevant.map(flow=>`<polyline points="${flow.points.map(fabricPoint).join(' ')}" fill="none" stroke="${flow.kind==='refill'?'#e5a2c5':flow.owner==='tensor'?'#bfa0ff':flow.owner==='rt'?'#edba76':'#6ad5bb'}" stroke-width="${selectedId!==null?9:5}" opacity="${selectedId!==null?.85:.38}" vector-effect="non-scaling-stroke"/>`).join('');}
 else {
  const physical=new Map();for(const link of f.links){const key=[fabricPoint(link.from),fabricPoint(link.to)].sort().join('|');const old=physical.get(key);if(!old||link.load>old.load)physical.set(key,link);}
  drawing=[...physical.values()].map(link=>`<line x1="${link.from.x*100+50}" y1="${link.from.y*100+50}" x2="${link.to.x*100+50}" y2="${link.to.y*100+50}" stroke="${fabricColor(link.load)}" stroke-width="${5+Math.min(1.5,link.load)*4}" opacity="${.3+Math.min(1,link.load)*.35}"/>`).join('');
  drawing+=f.hotspots.filter(l=>l.avgQueue>5).map(link=>`<circle cx="${(link.from.x+link.to.x)/2*100+50}" cy="${(link.from.y+link.to.y)/2*100+50}" r="29" fill="#ee8e6730" stroke="#eea06d" stroke-width="3"/>`).join('');
 }
 const focused=f.links.find(l=>l.key===state.fabricHotspot);if(focused)drawing+=`<line x1="${focused.from.x*100+50}" y1="${focused.from.y*100+50}" x2="${focused.to.x*100+50}" y2="${focused.to.y*100+50}" stroke="#fff1ac" stroke-width="17" opacity=".95"/>`;
 grid.insertAdjacentHTML('beforeend',`<svg class="fabric-overlay" viewBox="0 0 1600 1200" preserveAspectRatio="none" aria-hidden="true">${drawing}</svg>`);
 for(const block of grid.querySelectorAll('.chip-block:not(.ghost)')){const id=Number(block.dataset.id),flows=f.flows.filter(flow=>flow.fromId===id||flow.toId===id);if(flows.length){const maxDelay=Math.max(...flows.map(flow=>flow.queueDelay));block.classList.toggle('fabric-block-hot',maxDelay>6);block.title=`${MODULES[block.dataset.type].name} · 拖动移动 · 最长路径 ${Math.max(...flows.map(flow=>flow.hops))} 跳 · 最大额外排队 ${maxDelay.toFixed(1)} 周期`;}}
}

export function renderFabricDiagnostics(root,state,ui){
 const m=metrics(state),f=m.fabric,{icon,esc}=ui;
 const select=document.querySelector('#workload-select');select.value=state.workload??'balanced';
 for(const button of document.querySelectorAll('[data-fabric-layer]')){const active=button.dataset.fabricLayer===(state.fabricLayer??'congestion');button.classList.toggle('active',active);button.setAttribute('aria-pressed',active);}
 const identity=JSON.stringify({n:m.n,clock:state.clock,process:state.process,workload:state.workload??'balanced'});
 const saved=state.layoutReference,reference=saved?.model===FABRIC_MODEL&&Number.isFinite(saved.score)&&Number.isFinite(saved.tf)&&Number.isFinite(saved.latency)?saved:null;
 const relative=reference&&reference.score?((m.score-reference.score)/reference.score*100):0;
 const delta=reference?`<div class="fabric-comparison"><div><span>${reference.identity===identity?'同配置布局对照':'配置或负载已变化，差异不只来自布局'}</span><strong class="${relative<0?'loss':'gain'}">${fabricDelta(relative)}% <small>综合得分</small></strong></div><div><span>参考 / 当前</span><strong>${ui.fmt(reference.score)} <em>→</em> ${ui.fmt(m.score)}</strong><small>通信延迟 ${reference.latency.toFixed(1)} → ${f.avgLatency.toFixed(1)} 周期</small></div><button class="subtle-button" id="clear-layout-reference">清除对照</button></div>`:`<div class="fabric-reference-empty">${icon('layers')}记录当前布局，再拖动模块；对照会显示相同配置下的得分与通信延迟变化。</div>`;
 const longest=[...f.flows].sort((a,b)=>b.latency-a.latency||b.hops-a.hops)[0];
 const label=id=>{const b=state.blocks.find(b=>b.id===id);return b?`${MODULES[b.type].short} #${id}`:'模块';};
 const hotspotRows=f.hotspots.length?f.hotspots.slice(0,3).map((l,i)=>`<button class="fabric-hotspot" data-link="${esc(l.key)}"><span class="hotspot-number">0${i+1}</span><div><strong>(${l.from.x}, ${l.from.y}) → (${l.to.x}, ${l.to.y})</strong><small>平均排队 ${l.avgQueue.toFixed(1)} 包 · 峰值积压 ${l.maxQueue} 包</small></div><span style="color:${fabricColor(l.load)}">${Math.round(l.load*100)}%<small>链路压力</small></span></button>`).join(''):`<div class="fabric-no-hotspot">${icon('check')}链路分布均衡，当前没有明显拥塞热点。</div>`;
 root.innerHTML=`<div class="fabric-panel-heading"><div><span class="business-kicker">ON-CHIP NETWORK / PACKET SIMULATION</span><h2>${icon('activity')}片上互联分析 <span class="live-badge"><i></i>布局实时生效</span></h2></div><div><button class="subtle-button" id="record-layout-reference">${icon('save')}记录布局对照</button><button class="icon-button" id="fabric-model-help" aria-label="查看互联模型说明" title="互联模型说明">${icon('help')}</button></div></div>
 <div class="fabric-stat-grid"><div><span>平均通信距离</span><strong id="fabric-distance">${f.avgDistance.toFixed(2)} <small>跳</small></strong><em>固定 XY 路由 · 每跳一周期</em></div><div><span>平均通信延迟</span><strong id="fabric-latency">${f.avgLatency.toFixed(2)} <small>cyc</small></strong><em>含 ${f.queueDelay.toFixed(2)} 周期排队</em></div><div><span>峰值链路压力</span><strong id="fabric-load" class="${f.peakLoad>1?'loss':''}">${Math.round(f.peakLoad*100)}<small>%</small></strong><em>${f.congestedLinks} 条繁忙链路 · >100% 会积压</em></div><div><span>布局有效算力</span><strong id="fabric-efficiency">${m.theoreticalTf?fabricPercent(m.tf/m.theoreticalTf):'—'}</strong><em>互联动态功耗 +${m.networkPower} W</em></div></div>
 <div class="fabric-analysis-columns"><section class="fabric-throughput"><div class="fabric-section-label">理论峰值 → 有效性能 <span>${WORKLOADS[state.workload??'balanced'].name}</span></div><div class="fabric-throughput-values"><span>${m.theoreticalTf.toFixed(2)} <small>TFLOPS</small></span><i>→</i><strong>${m.tf.toFixed(2)} <small>TFLOPS</small></strong></div><div class="fabric-efficiency-track"><i style="width:${m.theoreticalTf?m.tf/m.theoreticalTf*100:0}%"></i></div><p>路径长会增加传输时间，共用链路会消耗服务容量；队列积压会进一步降低计算单元利用率。</p><div class="fabric-engine-stats"><span>${ui.fmt(f.injected)} 包注入</span><span>${ui.fmt(f.delivered)} 包完成</span><span>${ui.fmt(f.backlog)} 包在途 / 排队</span></div></section><section class="fabric-hotspots"><div class="fabric-section-label">链路热点 <span>点击在芯片上定位</span></div>${hotspotRows}</section></div>
 <div class="fabric-advice"><span>${icon('target')}</span><p>${f.peakLoad>1?'存在容量超载。分散热点附近的缓存与显存入口，让通信流走不同路径。':'可将缓存靠近主要计算簇，并分散显存入口，减少数据包经过的跳数。'}${longest?` 最慢通信：${label(longest.fromId)} → ${label(longest.toId)}，${longest.hops} 跳，约 ${longest.latency.toFixed(1)} 周期。`:''}</p></div>
 ${delta}<div class="fabric-model-note">16 × 12 Mesh · ${f.capacity} 包 / 链路 / 周期 · 预热 ${f.warmup} 周期 + 统计 ${f.cycles} 周期 · 合成通信负载，非硬件实测</div>`;
 root.querySelector('#record-layout-reference').onclick=()=>{state.layoutReference={model:FABRIC_MODEL,score:m.score,tf:m.tf,latency:f.avgLatency,identity};ui.refresh();ui.save();ui.toast('已记录参考布局。现在拖动模块，比较性能与延迟。');};
 root.querySelector('#clear-layout-reference')?.addEventListener('click',()=>{delete state.layoutReference;ui.refresh();ui.save();});
 for(const button of root.querySelectorAll('[data-link]'))button.onclick=()=>{state.fabricHotspot=button.dataset.link;state.fabricLayer='congestion';ui.refresh();document.querySelector('#chip-workspace').scrollIntoView({behavior:'smooth',block:'center'});};
 root.querySelector('#fabric-model-help').onclick=()=>ui.dialog(`<div class="dialog-top"><span class="eyebrow">MESH PACKET MODEL / V1</span><button class="icon-button" data-close aria-label="关闭弹窗">${icon('close')}</button></div><h2>摆放，如何改变性能？</h2><div class="guide-steps"><div class="guide-step"><span class="guide-number">01</span><div><strong>距离决定跳数</strong><p>模块中心连接到最近的网格路由节点。计算核心访问最近缓存，缓存访问最近显存控制器；沿 X 再沿 Y 传输，每跳一周期，另计 2 周期端点开销。</p></div></div><div class="guide-step"><span class="guide-number">02</span><div><strong>通信流会争用链路</strong><p>系统逐周期注入请求、数据返回、显存回填和指令调度包。每条有向链路每周期最多服务 3 包，超出的包进入 FIFO 队列，后续周期继续传输。</p></div></div><div class="guide-step"><span class="guide-number">03</span><div><strong>等待会影响跑分与产品</strong><p>实际测得的队列积压、完成率与路径跳数影响 SM、TC、RT 利用率，传输活动增加功耗。提高频率会加大注入压力；三种负载会产生不同的热点。</p></div></div></div><p class="dialog-description">互联经过模块上方的抽象金属层，不将模块视为布线障碍。这是可重复的游戏级分组仿真，不执行 CUDA 或真实 GPU 指令。旧产品保留立项快照，新架构需要重新测试认证。</p><button class="primary-button" data-close>继续设计</button>`);
}
export function fabricRunSummary(run){const f=run.fabric;return f?`<div class="run-fabric-summary"><span>${f.profileName??WORKLOADS[f.workload]?.name??'均衡图形'} · ${f.avgDistance.toFixed(1)} 跳</span><strong>通信 ${f.avgLatency.toFixed(1)} cyc</strong><span>峰值压力 ${Math.round(f.peakLoad*100)}%</span></div>`:'<div class="run-fabric-summary"><span>旧模型测试记录 · 当前布局请重新测试</span></div>';}
